int credits_private_scene_due(int scene, int g, int b) {
    switch (scene) {
    case SC_WIPE: switch (g) {
        case 0: return 1;
        default: return 0; }
    case SC_CLEAR_WIPE: switch (g) {
        case 0: return 1;
        default: return 0; }
    case SC_CLEAR: switch (g) {
        case 0: return 1;
        default: return 0; }
    case SC_OCEAN_B: switch (g) {
        case 0: return b % 2 == 0;
        case 1: return 1;
        default: return 0; }
    case SC_OCEAN_C: switch (g) {
        case 0: return b % 2 == 0;
        case 1: return 1;
        case 2: return 1;
        case 3: return 1;
        case 4: return 1;
        default: return 0; }
    case SC_OCEAN_D: switch (g) {
        case 0: return 1;
        case 1: return 1;
        default: return 0; }
    case SC_TYPEWRITE: switch (g) {
        case 0: return 1;
        default: return 0; }
    case SC_TITLE: switch (g) {
        case 0: return b == 64;
        case 1: return b == 128;
        case 2: return b == 192;
        case 3: return b == 256;
        case 4: return b == 320;
        case 5: return b == 384;
        case 6: return b == 448;
        case 7: return b == 512;
        case 8: return b == 576;
        case 9: return b == 640;
        case 10: return b == 704;
        case 11: return b == 768;
        default: return 0; }
    case SC_BEATS: switch (g) {
        case 0: return (b % 64 < 48 && b % 4 == 0);
        case 1: return (b % 64 >= 48 && b % 2 == 0);
        default: return 0; }
    case SC_BEATS_LR: switch (g) {
        case 0: return (b % 64 < 48 && b % 4 == 0);
        case 1: return (b % 64 >= 48 && b % 2 == 0);
        default: return 0; }
    case SC_FUNDING: switch (g) {
        case 0: return 1;
        case 1: return 1;
        default: return 0; }
    case SC_DATES: switch (g) {
        case 0: return b < 512;
        case 1: return b < 764;
        case 2: return b == 764;
        case 3: return (b % 4 == 0 && b < 1024);
        case 4: return 1;
        default: return 0; }
    case SC_WEATHER: switch (g) {
        case 0: return (b % 64 == 0 && b < 512);
        case 1: return (b % 32 == 0 && b < 768);
        case 2: return b == 764;
        case 3: return (b % 4 == 0 && b < 1024);
        case 4: return 1;
        default: return 0; }
    case SC_REDRAW_UI: switch (g) {
        case 0: return b == 0;
        case 1: return b == 0;
        case 2: return b == 2;
        case 3: return b == 3;
        case 4: return b == 4;
        case 5: return b == 5;
        case 6: return b == 6;
        case 7: return b == 7;
        default: return 0; }
    case SC_LOADINGBAR: switch (g) {
        case 0: return b == 0;
        case 1: return b == 1;
        case 2: return (b < 240 && b % 8 == 0);
        case 3: return 1;
        case 4: return b < 240;
        case 5: return 1;
        case 6: return b < 240;
        default: return 0; }
    case SC_FASTLOAD: switch (g) {
        case 0: return b == 0;
        case 1: return b == 1;
        case 2: return 1;
        case 3: return 1;
        default: return 0; }
    case SC_ERROR: switch (g) {
        case 0: return b == 0;
        case 1: return b == 0;
        default: return 0; }
    case SC_FUNDINGX2: switch (g) {
        case 0: return 1;
        case 1: return 1;
        case 2: return 1;
        case 3: return 1;
        default: return 0; }
    case SC_ACCESSPOINTS: switch (g) {
        case 0: return (b < 20 && b % 2 == 0);
        case 1: return b == 20;
        case 2: return b == 0;
        case 3: return (b % 8 == 0 && b < 976);
        case 4: return b == 968;
        default: return 0; }
    case SC_FDG_SINGLE: switch (g) {
        case 0: return b == 0;
        case 1: return 1;
        default: return 0; }
    case SC_FDG_DOWN: switch (g) {
        case 0: return 1;
        case 1: return 1;
        default: return 0; }
    case SC_POWEROFF: switch (g) {
        case 0: return 1;
        case 1: return 1;
        case 2: return 1;
        case 3: return 1;
        default: return 0; }
    default: return 0;
    }
}

void credits_private_corrupt_text(credits_private_Random *random,char *text,int chance,const char *ignore) {
    static const char replacements[]="...  `=/?-$%";
    for (char *p=text;*p;p++) {
        if (*p=='\n') continue;
        /* randint is consumed even for ignored characters, per Python and. */
        if (credits_private_random_int(random,1,1000)<chance && !strchr("@~\n",*p) && !strchr(ignore,*p))
            *p=replacements[credits_private_random_below(random,12)];
    }
}
void credits_private_data_init(credits_private_Text *texts,credits_private_Memory *memory,credits_private_Random *random) {
    for (int i=0;i<TEXT_COUNT;i++) {
        const credits_private_TextDefinition *def=&credits_private_data_text_definitions[i];
        credits_private_Text *text=&texts[i];
        *text=(credits_private_Text){0}; text->bytes=def->bytes; text->repeat=def->repeat;
        text->raw=credits_private_mem_resize(memory,NULL,0,(size_t)def->bytes+1);
        int offset=0;
        for (int j=0;j<def->count;j++) {
            const credits_private_DataSegment *seg=&def->segments[j];
            int size=(int)strlen(seg->text);
            memcpy(text->raw+offset,seg->text,(size_t)size+1);
            if (seg->chance) credits_private_corrupt_text(random,text->raw+offset,seg->chance,seg->ignore);
            offset+=size;
        }
        if (offset!=text->bytes) credits_private_credits_fail("generated text size mismatch");
        if (def->words) {
            text->line_count=1;
            for (int j=0;j<text->bytes;j++) if (text->raw[j]=='\n') text->line_count++;
            text->lines=credits_private_mem_resize(memory,NULL,0,(size_t)text->line_count*sizeof(credits_private_WordLine));
            int line=0,start=0;
            for (int j=0;j<=text->bytes;j++) if (!text->raw[j] || text->raw[j]=='\n') {
                text->raw[j]=0;
                credits_private_WordLine *l=&text->lines[line++];
                l->value=text->raw+start; l->length=j-start; l->words=1;
                for (int k=start;k<j;k++) if (text->raw[k]=='#') l->words++;
                start=j+1;
            }
            if (line!=text->line_count) credits_private_credits_fail("generated line count mismatch");
        }
    }
}
void credits_private_data_destroy(credits_private_Text *texts,credits_private_Memory *memory) {
    for (int i=0;i<TEXT_COUNT;i++) {
        credits_private_mem_free(memory,texts[i].raw,(size_t)texts[i].bytes+1);
        credits_private_mem_free(memory,texts[i].lines,(size_t)texts[i].line_count*sizeof(credits_private_WordLine));
        texts[i]=(credits_private_Text){0};
    }
}
size_t credits_private_data_readonly_size(void) {
    size_t size=sizeof(credits_private_data_text_definitions)+sizeof(credits_private_scene_definitions);
    for (int i=0;i<TEXT_COUNT;i++) {
        const credits_private_TextDefinition *d=&credits_private_data_text_definitions[i];
        size+=strlen(d->name)+1+(size_t)d->count*sizeof(credits_private_DataSegment);
        for (int j=0;j<d->count;j++) size+=strlen(d->segments[j].text)+1+strlen(d->segments[j].ignore)+1;
    }
    for (int i=0;i<SC_COUNT;i++) size+=strlen(credits_private_scene_definitions[i].name)+1+(size_t)credits_private_scene_definitions[i].count*sizeof(int);
    return size;
}


