#include <string.h>

uint32_t credits_private_cell_pack(uint32_t ch,int fg,int bg,int style) {
    return ch | (uint32_t)fg<<16 | (uint32_t)bg<<22 | (uint32_t)style<<28;
}
uint32_t credits_private_canvas60_style(const char *code) {
    int fg=39,bg=49,style=1;
    const char *p=code;
    while (*p) {
        if (*p++!='\033' || *p++!='[') credits_private_credits_fail("invalid SGR");
        for (;;) {
            int n=0;
            while (*p>='0' && *p<='9') n=n*10+(*p++-'0');
            if (!n) { fg=39; bg=49; style=0; }
            else if (n==1 || n==2 || n==22) style=n==22 ? 0:n;
            else if (n>=30 && n<=39) fg=n;
            else if (n>=40 && n<=49) bg=n;
            else credits_private_credits_fail("unsupported SGR");
            if (*p==';') { p++; continue; }
            if (*p++!='m') credits_private_credits_fail("invalid SGR terminator");
            break;
        }
    }
    return credits_private_cell_pack(0,fg,bg,style);
}
static uint32_t credits_private_charbuf60_decode(const char **text) {
    const unsigned char *p=(const unsigned char *)*text;
    uint32_t ch=*p++;
    if (ch>=0xc2 && ch<=0xdf && p[0]>=0x80 && p[0]<=0xbf) ch=((ch&31)<<6)|(*p++&63);
    else if (ch>=0x80) credits_private_credits_fail("unsupported UTF-8");
    *text=(const char *)p; return ch;
}
void credits_private_canvas60_put(credits_private_Canvas *c,int x,int y,uint32_t cell) {
    /* Clipping is explicit for effects; text uses bounded, scrolling regions. */
    if (x<0 || x>=60 || y<0 || y>=20) { c->clipped_cells++; return; }
    c->cells[y*60+x]=cell;
}
void credits_private_canvas_chars(credits_private_Canvas *c,int x,int y,const uint32_t *chars,int length,const char *code) {
    uint32_t style=credits_private_canvas60_style(code);
    for (int i=0;i<length;i++) credits_private_canvas60_put(c,x+i,y,style|chars[i]);
}
void credits_private_canvas_string_cursor(credits_private_Canvas *c,int x,int y,const char *text,const char *code,int cursor_index) {
    uint32_t style=credits_private_canvas60_style(code); int i=0,origin=x;
    while (*text) {
        uint32_t ch=credits_private_charbuf60_decode(&text);
        int cursor=i==cursor_index || (cursor_index==-1 && !*text); i++;
        if (ch=='\n') { y++; x=origin; }
        else if (ch=='\r') x=origin;
        else credits_private_canvas60_put(c,x++,y,style|ch|(cursor ? CREDITS_PRIVATE_CELL_CURSOR:0));
    }
}
void credits_private_canvas_string(credits_private_Canvas *c,int x,int y,const char *text,const char *code) {
    credits_private_canvas_string_cursor(c,x,y,text,code,-2);
}
void credits_private_canvas_char(credits_private_Canvas *c,int x,int y,const char *text,const char *code) { credits_private_canvas_string(c,x,y,text,code); }
static void credits_private_charbuf60_valid_region(credits_private_TextRegion r) {
    if (r.x<0 || r.y<0 || r.w<=0 || r.h<=0 || r.x+r.w>60 || r.y+r.h>20)
        credits_private_credits_fail("invalid 60x20 text region");
}
void credits_private_canvas60_clear_region(credits_private_Canvas *c,credits_private_TextRegion r) {
    credits_private_charbuf60_valid_region(r);
    for (int y=r.y;y<r.y+r.h;y++) for (int x=r.x;x<r.x+r.w;x++) c->cells[y*60+x]=credits_private_cell_pack(' ',39,49,0);
}
void credits_private_canvas_clear(credits_private_Canvas *c) { credits_private_canvas60_clear_region(c,(credits_private_TextRegion){0,0,60,20}); c->background=49; }
void credits_private_canvas_init(credits_private_Canvas *c,credits_private_Memory *memory) { (void)memory; memset(c,0,sizeof(*c)); credits_private_canvas_clear(c); }
void credits_private_canvas_render(credits_private_Canvas *c) { (void)c; } /* Writes are already committed. */
void credits_private_canvas_destroy(credits_private_Canvas *c) { (void)c; }
credits_private_TextFlow credits_private_canvas60_flow(credits_private_Canvas *c,credits_private_TextRegion r,int clear) {
    credits_private_charbuf60_valid_region(r); if (clear) credits_private_canvas60_clear_region(c,r);
    return (credits_private_TextFlow){c,r,0,0};
}
void credits_private_canvas60_newline(credits_private_TextFlow *f) {
    f->col=0;
    if (++f->row<f->region.h) return;
    credits_private_TextRegion r=f->region;
    for (int y=0;y<r.h-1;y++) memmove(f->canvas->cells+(r.y+y)*60+r.x,
        f->canvas->cells+(r.y+y+1)*60+r.x,(size_t)r.w*sizeof(uint32_t));
    credits_private_canvas60_clear_region(f->canvas,(credits_private_TextRegion){r.x,r.y+r.h-1,r.w,1});
    f->row=r.h-1; f->canvas->scrolled_rows++;
}
static int credits_private_charbuf60_whitespace(uint32_t ch) { return ch==' ' || ch==160; }
void credits_private_canvas60_line(credits_private_TextFlow *f,const char *text,const char *code,int cursor_last) {
    uint32_t style=credits_private_canvas60_style(code);
    const char *end=text+strlen(text);
    while (end>text && end[-1]==' ') end--;
    while (text<end) {
        const char *word=text; int length=0;
        uint32_t first=credits_private_charbuf60_decode(&word);
        if (first=='\n') { credits_private_canvas60_newline(f); text=word; continue; }
        if (first=='\r') { f->col=0; text=word; continue; }
        if (credits_private_charbuf60_whitespace(first) && f->col==f->region.w) { text=word; continue; }
        length=1;
        if (!credits_private_charbuf60_whitespace(first)) {
            while (word<end) {
                const char *next=word; uint32_t ch=credits_private_charbuf60_decode(&next);
                if (credits_private_charbuf60_whitespace(ch) || ch=='\n' || ch=='\r') break;
                length++; word=next;
            }
            if (length<=f->region.w && f->col+length>f->region.w) credits_private_canvas60_newline(f);
        }
        while (text<word) {
            uint32_t ch=credits_private_charbuf60_decode(&text);
            if (f->col==f->region.w) credits_private_canvas60_newline(f);
            credits_private_canvas60_put(f->canvas,f->region.x+f->col++,f->region.y+f->row,
                style|ch|((cursor_last && text==end) ? CREDITS_PRIVATE_CELL_CURSOR:0));
        }
    }
}


